import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.D3xAlClj.js";const l="/entislng/v4/assets/9c0cc64ac64dbfd5-20261015000320-dm3xo6u.TppFhRZO.png",u=JSON.parse('{"title":"大罐区软件性能优化指南","description":"","frontmatter":{"title":"大罐区软件性能优化指南","date":"2026-10-14T16:03:21.000Z","lastmod":"2026-11-24T18:47:00.000Z"},"headers":[],"relativePath":"guide/1266.md","filePath":"guide/帮助文档/专项说明/大罐区软件性能优化指南.md"}'),i={name:"guide/1266.md"};function n(h,a,s,d,p,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="大罐区软件性能优化指南" tabindex="-1">大罐区软件性能优化指南 <a class="header-anchor" href="#大罐区软件性能优化指南" aria-label="Permalink to &quot;大罐区软件性能优化指南&quot;">​</a></h1><p>‍</p><p>当软件配置较多罐数时,同时电脑性能又不佳的情况下,性能问题就会显现出来,可能会导致软件运行异常,严重情况下,系统崩溃,数据丢失.所以在软件里进行适当的配置优化是必要的.配置优化的目的是为了系统能正常稳定运行,主要策略是通过减少数据保存,数据计算等方式</p><h4 id="第一步-减少全局数据保存期限" tabindex="-1">第一步，减少全局数据保存期限 <a class="header-anchor" href="#第一步-减少全局数据保存期限" aria-label="Permalink to &quot;第一步，减少全局数据保存期限&quot;">​</a></h4><p>打开菜单“系统配置/全局设置”，在打开的窗体中，选择数据保存这一项，如下图：</p><h4 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h4><p><img src="'+l+'" alt=""></p><h4 id="第二步-减少罐监控模块中的历史数据和实时数据保存" tabindex="-1">第二步，减少罐监控模块中的历史数据和实时数据保存 <a class="header-anchor" href="#第二步-减少罐监控模块中的历史数据和实时数据保存" aria-label="Permalink to &quot;第二步，减少罐监控模块中的历史数据和实时数据保存&quot;">​</a></h4><p>打开菜单 &quot;罐监控配置/选项&quot;，在打开的窗体中，选择数据保存这一项，如下图：</p><h4 id="第三步-适当调慢定时任务项" tabindex="-1">第三步，适当调慢定时任务项 <a class="header-anchor" href="#第三步-适当调慢定时任务项" aria-label="Permalink to &quot;第三步，适当调慢定时任务项&quot;">​</a></h4><p>如果有配置较多的定时任务项，则请适当调慢定时间隔，一般定时任务项有如定时备份数据库，定时导出报表，定时执行仪表命令（伺服密度，多点温度，测水等）</p><h4 id="第四步-适当调慢通讯轮询时间" tabindex="-1">第四步，适当调慢通讯轮询时间 <a class="header-anchor" href="#第四步-适当调慢通讯轮询时间" aria-label="Permalink to &quot;第四步，适当调慢通讯轮询时间&quot;">​</a></h4><p>这个根据通讯的情况适当调整，其中重要的参考依据是通讯收发的时间差，通讯轮询间隔不要小于通讯的收发时间差：</p><ul><li>如果有Modbus输出模块配置的，则在第三方系统如DCS中，适当调慢轮询间隔，可以减轻软件负荷。</li></ul><h4 id="第五步-缩减罐容表" tabindex="-1">第五步，缩减罐容表 <a class="header-anchor" href="#第五步-缩减罐容表" aria-label="Permalink to &quot;第五步，缩减罐容表&quot;">​</a></h4><p>有些罐容表数据量非常大，可能一个罐会超过 1 万多条记录。罐数不多时，无需优化；但当罐数较多时，罐容表表格总记录数会比较大，也会导致性能问题（罐容表总记录数控制在 100 万行以内）。此时，请适当缩减罐容表。比较简单的一个方法是重新导入时，采用隔行导入的方法，间隔一行，就可以缩减一半的罐容表：</p><h4 id="第六步-安装大容量数据库版本" tabindex="-1">第六步,安装大容量数据库版本 <a class="header-anchor" href="#第六步-安装大容量数据库版本" aria-label="Permalink to &quot;第六步,安装大容量数据库版本&quot;">​</a></h4><p>默认安装的数据库版本是Express版本，此版本有免费授权，一般情况下，可以满足现场使用，但如果罐数较多，历史数据保存期限较长，且希望还能保证数据库读写性能的情况下，则有必要使用开发版本的数据库，此版本数据库在无互联网联接的情况下使用是可以的。 下载链接：<a href="https://res.softcool.cn/d/kuake/Software/SqlServer/SqlServer2017/SqlServer2017_Developer_EN.zip" target="_blank" rel="noreferrer">英文版下载</a>​<a href="https://res.softcool.cn/d/kuake/Software/SqlServer/SqlServer2017/SqlServer2017_Developer_CN.zip" target="_blank" rel="noreferrer">中文版下载</a></p><h4 id="第七步-升级硬件" tabindex="-1">第七步，升级硬件 <a class="header-anchor" href="#第七步-升级硬件" aria-label="Permalink to &quot;第七步，升级硬件&quot;">​</a></h4><p>经过以上优化步骤，如果依然还是遇到性能问题，则最有效的办法就是升级电脑硬件，重点升级对像是硬盘，推荐升级高性能的固态硬盘，性能较强的硬盘有较快的读写速度，可以让数据读写顺畅完成。升级CPU和内存也能有效提高软件执行效率，在预算充分的情况下，推荐升级到当前主流配置。</p>',20)])])}const f=e(i,[["render",n]]);export{u as __pageData,f as default};
